class Parcel:
    def __init__(self, name, weight): self.name, self.weight = name, weight
    def __str__(self): return self.name
    def __lt__(self, other):
        if not isinstance(other, Parcel): return NotImplemented
        return self.weight < other.weight
def solve(data):
    return [str(p) for p in sorted([Parcel(row['name'], row['weight']) for row in data])]
